live=set()
for m in re.finditer(r'^### ([\d, ]+)\s*$', R, re.M):
    live |= {int(x) for x in re.findall(r'\d+', m.group(1))}
print("excised:", len(exc), " live:", len(live))
hits=[]
for f in sorted(glob.glob("*.py")):
    for i,l in enumerate(open(f,encoding="utf-8"),1):
        for m in re.finditer(r'register\s+(\d{3,4})', l, re.I):
            n=int(m.group(1))
            hits.append((f,i,n,"EXCISED" if n in exc else ("live" if n in live else "absent-never-assigned")))
for h in hits: print(f"  {h[0]}:{h[1]}  register {h[2]}  -> {h[3]}")
print("total citations in instruments:", len(hits), " of which excised:", sum(1 for h in hits if h[3]=="EXCISED"))
