import re, glob, py_compile
W=open("WORKING-REGISTER.md",encoding="utf-8").read()
exc=set()
for m in re.finditer(r'^<!-- EXCISED ([\d, ]+) :', W, re.M):
    exc |= {int(x) for x in re.findall(r'\d+', m.group(1))}
R=open("The_Method_1_6___The_Register-2.md",encoding="utf-8").read()
live=set()
for m in re.finditer(r'^### ([\d, ]+)\s*$', R, re.M):
    live |= {int(x) for x in re.findall(r'\d+', m.group(1))}
bad=[]; keep=[]
for f in sorted(glob.glob("*.py")):
    for i,l in enumerate(open(f,encoding="utf-8"),1):
        for m in re.finditer(r'register\s+(\d{3,4})', l, re.I):
            n=int(m.group(1))
            (bad if n in exc else keep).append((f,i,n))
print("dangling pointers to excised entries:", len(bad), bad)
print("live citations retained:", sorted({(f,n) for f,i,n in keep}))
err=0
for f in sorted(glob.glob("*.py")):
    try: py_compile.compile(f, doraise=True)
    except Exception as e: err+=1; print("COMPILE FAIL", f, e)
print("instruments compiled clean:", 23-err, "/ 23")
